import { useEffect, useRef, useState } from 'react';
import { X, RotateCcw, Send } from 'lucide-react';
import {
  StyledWidget,
  StyledWidgetHeader,
  StyledWidgetAvatar,
  StyledWidgetLogoBadge,
  StyledWidgetHeaderText,
  StyledWidgetName,
  StyledWidgetStatus,
  StyledHeaderIconBtn,
  StyledMessageList,
  StyledWidgetInput,
  StyledFakeInput,
  StyledSendBtn,
} from './styles';
import { BOT_NAME, CHAT_SCRIPT, type ScriptStep } from './script';
import { MessageBubble } from './MessageBubble';
import { TypingIndicator } from './TypingIndicator';
import { CtaCard } from './CtaCard';
import { TipaLogo } from './TipaLogo';

interface ChatbotWidgetProps {
  exiting: boolean;
  onClose: () => void;
  onCtaClick: () => void;
}

type RenderedItem =
  | { kind: 'ai' | 'user'; text: string; typingMs: number; key: string }
  | { kind: 'cta'; key: string };

export function ChatbotWidget({ exiting, onClose, onCtaClick }: ChatbotWidgetProps) {
  const [items, setItems] = useState<RenderedItem[]>([]);
  const [showTyping, setShowTyping] = useState(false);
  const [runId, setRunId] = useState(0);
  const listRef = useRef<HTMLDivElement | null>(null);
  const timersRef = useRef<number[]>([]);

  const scrollToBottom = () => {
    const el = listRef.current;
    if (!el) return;
    requestAnimationFrame(() => {
      el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' });
    });
  };

  const clearTimers = () => {
    timersRef.current.forEach((id) => window.clearTimeout(id));
    timersRef.current = [];
  };

  const schedule = (fn: () => void, ms: number) => {
    const id = window.setTimeout(fn, ms);
    timersRef.current.push(id);
  };

  useEffect(() => {
    clearTimers();
    setItems([]);
    setShowTyping(false);

    let cursor = 0;

    const playNext = () => {
      if (cursor >= CHAT_SCRIPT.length) return;
      const step: ScriptStep = CHAT_SCRIPT[cursor];

      schedule(() => {
        if (step.kind === 'ai') {
          setShowTyping(true);
          scrollToBottom();
          schedule(() => {
            setShowTyping(false);
            setItems((prev) => [
              ...prev,
              {
                kind: 'ai',
                text: step.text,
                typingMs: step.typingMs,
                key: `ai-${runId}-${cursor}`,
              },
            ]);
            scrollToBottom();
            schedule(() => {
              cursor += 1;
              playNext();
              scrollToBottom();
            }, step.typingMs + 250);
          }, 700);
        } else if (step.kind === 'user') {
          setItems((prev) => [
            ...prev,
            {
              kind: 'user',
              text: step.text,
              typingMs: step.typingMs,
              key: `user-${runId}-${cursor}`,
            },
          ]);
          scrollToBottom();
          schedule(() => {
            cursor += 1;
            playNext();
            scrollToBottom();
          }, step.typingMs + 250);
        } else {
          // cta
          setItems((prev) => [...prev, { kind: 'cta', key: `cta-${runId}-${cursor}` }]);
          scrollToBottom();
          cursor += 1;
        }
      }, step.delayBeforeMs);
    };

    playNext();

    return () => {
      clearTimers();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [runId]);

  const handleRestart = () => {
    clearTimers();
    setRunId((r) => r + 1);
  };

  return (
    <StyledWidget $exiting={exiting}>
      <StyledWidgetHeader>
        <StyledWidgetAvatar>
          <StyledWidgetLogoBadge>
            <TipaLogo />
          </StyledWidgetLogoBadge>
        </StyledWidgetAvatar>
        <StyledWidgetHeaderText>
          <StyledWidgetName>{BOT_NAME}</StyledWidgetName>
          <StyledWidgetStatus>온라인</StyledWidgetStatus>
        </StyledWidgetHeaderText>
        <StyledHeaderIconBtn onClick={handleRestart} aria-label="다시 보기">
          <RotateCcw size={16} />
        </StyledHeaderIconBtn>
        <StyledHeaderIconBtn onClick={onClose} aria-label="닫기">
          <X size={18} />
        </StyledHeaderIconBtn>
      </StyledWidgetHeader>

      <StyledMessageList ref={listRef}>
        {items.map((item) => {
          if (item.kind === 'cta') {
            return <CtaCard key={item.key} onClick={onCtaClick} />;
          }
          return (
            <MessageBubble
              key={item.key}
              side={item.kind}
              text={item.text}
              typingMs={item.typingMs}
              onComplete={scrollToBottom}
            />
          );
        })}
        {showTyping && <TypingIndicator />}
      </StyledMessageList>

      <StyledWidgetInput>
        <StyledFakeInput>AI가 응답 중이에요...</StyledFakeInput>
        <StyledSendBtn disabled aria-label="전송">
          <Send size={16} />
        </StyledSendBtn>
      </StyledWidgetInput>
    </StyledWidget>
  );
}
