import { useEffect, useState } from 'react';
import { StyledBubble, StyledMessageRow } from './styles';

interface MessageBubbleProps {
  side: 'ai' | 'user';
  text: string;
  typingMs: number;
  onComplete?: () => void;
}

export function MessageBubble({ side, text, typingMs, onComplete }: MessageBubbleProps) {
  const [visibleLength, setVisibleLength] = useState(0);

  useEffect(() => {
    setVisibleLength(0);
    const total = text.length;
    if (total === 0) {
      onComplete?.();
      return;
    }

    const stepMs = Math.max(12, Math.floor(typingMs / total));
    let current = 0;
    const interval = setInterval(() => {
      current += 1;
      setVisibleLength(current);
      if (current >= total) {
        clearInterval(interval);
        onComplete?.();
      }
    }, stepMs);

    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text, typingMs]);

  return (
    <StyledMessageRow $side={side}>
      <StyledBubble $side={side}>{text.slice(0, visibleLength)}</StyledBubble>
    </StyledMessageRow>
  );
}
